function CoffeeTakeoutDialog:FreshTab()
    ---@type CommonTabToggleLeft
    local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, CommonTabToggleLeftPath)
    local area = ActionUtils.GetAllRegionPrimaryMapVo()
    local timeLimitVos = CfUtils.GetCf(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",true)
    local t = {}
    for i, v in pairs(area) do
        ---是否解锁的逻辑
        ----@type RegionPrimaryMapVo
        local vo = v
        local isUnlock, description = ActionUtils.IsUnlockRegionalPoint(vo.id)
        local redPointStatus = false
        if isUnlock then
            local isFinish = maidCoffeePlayerComponent:IsHaveFinishOrderByAreaId(vo.id)
            redPointStatus = (isFinish == 1)
        end
        table.insert(t, { text = v.name, redPointStatus = redPointStatus, func = function(data, index)
            if vo then
                if isUnlock then return 1 else
                    GameUtils.Toast(description)
                    return 0
                end
            end
            return 0
        end })
        if isUnlock and self.openArea == 0 then
            self.openArea = checkNumber(vo.id)
        end
    end
    env:SetAfterAction(function(index)
        print('--->>', index)
        ----@type RegionPrimaryMapVo
        local vo = area[index + 1]
        if vo then
            if self.openArea == checkNumber(vo.id) then return end
            self.openArea = checkNumber(vo.id)
            --CfUtils.CookieSave("TAKEOUT_SELECT_AREA",self.openArea)
            self.controller:SetExtraArgument(tostring(self.openArea))
            self:SetFilterType(self.openArea)
        end
    end)
    env:FillToggles(t, self.openArea, function(isSelected, index, curIndex, data, nodeEnv)
        --print('---->>', index, curIndex)
        ----@type RegionPrimaryMapVo
        local vo = area[index]
        local timeLimitVo = timeLimitVos[index]
        if vo then
            local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(vo.id)
            local isUnlock = ActionUtils.IsUnlockRegionalPoint(vo.id)
            nodeEnv:SetAreaLevel(isUnlock, lv, vo.takeawayIcon)
            if timeLimitVo then
                local num = isUnlock and string.format("%s",timeLimitVo.takeOutNum[lv] - maidCoffeePlayerComponent:GetTimeByArea(index) or string.format("%s",timeLimitVo.takeOutNum[lv]))
                local isToMax = maidCoffeePlayerComponent:IsAreaOrderMax(index)
                local isHaveReward = self:IsAreaOrderHaveReward(index)
                nodeEnv:SetAreaNum(isUnlock,num,isToMax,isHaveReward)
                if isUnlock then
                    local isAllOrderCold = maidCoffeePlayerComponent:IsAllAreaOrderCold(index)
                    local status = not isToMax
                    if isAllOrderCold then
                        status = false
                    end
                    nodeEnv:FreshRedPointStatus(status)
                else
                    nodeEnv:FreshRedPointStatus(false)
                end
            end
        end
    end)
end

function CoffeeTakeoutDialog:IsToMaxTime()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self.openArea)
    local timeLimitVo = CfUtils.GetCfVo(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",self.openArea)
    if vo then
        local lv, _ = ActionUtils.GetRegionalPointLikabilityLevel(vo.id)
        if timeLimitVo then
            local maxCount = timeLimitVo.takeOutNum[lv]
            return maidCoffeePlayerComponent:GetTimeByArea(self.openArea) >= tonumber(maxCount)
        end
    end
    return false
end

