    kTool.SetActive(self.EmptyNode.gameObject, visibility)
    if visibility then
        local goMB = GetLuaBehaviour(self.EmptyNode.gameObject, "Game.Behaviours.EmptyNodeMB")
        if not isNull(goMB) then
            if isNull(goMB.Env) then
                goMB:Init()
            end
            ---@type EmptyNodeMB
            local env = goMB.Env
            env:SetText(text)
        end
