---FreshOrderTackInfo
---剧情外卖小队信息
function CoffeeTakeoutDialog:FreshOrderTackInfo()
    kTool.DestroyGameObjectChildren(self.Situation.gameObject)
    local t = table.keys(self.teams)
    table.sort(t)
    local teamIds = t
    for i = 1, #teamIds do
        local teamId = teamIds[i]
        ---@type MaidCoffeeClerkSettingVo
        local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(teamId)
        local go = kTool.Instantiate(self.Situation.gameObject, self.ImgFleet.gameObject, false)
        kTool.SetActive(go, true)
        local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
        local vip = checkNumber(vo.vip)
        if status == MaidCoffeeConstants.TakeOutStatus.LOCKED then
            ---未解锁的
            if vip == 1 then
                CfUtils.SetUISwitchImage(go, 4)
            else
                CfUtils.SetUISwitchImage(go, 3)
            end
        elseif status == MaidCoffeeConstants.TakeOutStatus.IDLE then
            CfUtils.SetUISwitchImage(go, 1)
        else
            --working中的是
            CfUtils.SetUISwitchImage(go, 2)
        end
    end
end

function CoffeeTakeoutDialog:IsAreaOrderHaveReward(areaId)
    for i, v in pairs(self.originData) do
        if v.area == areaId and v.status == Status.FINISHED then
            return true
        end
    end
    return false
end

