function CoffeeTakeoutDialog:FillFilter()
    if self.CommonFilterNode then
        ---@type UICommonFilterMB
        local filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, 'Game.Behaviours.UICommonFilterMB')
        if not isNull(filterNodeEnv) then
            ----获取所有的区域数据
            local t = { { conditionType = 9999, typeDesc = localize('全部地区') } }
            local area = ActionUtils.GetAllRegionPrimaryMapVo()
            for i, v in pairs(area) do
                table.insert(t, { conditionType = checkNumber(v.id), typeDesc = v.name })
            end
            filterNodeEnv:InitSortTypeData(t)
            filterNodeEnv.selectIndex = 0  -- 设置后，首次点第一项也能响应了
            filterNodeEnv:SetCallback({}, function()
                local selectIndex = filterNodeEnv.selectIndex
                local sortTypeData = filterNodeEnv.sortTypeList[selectIndex]
                self:SetFilterType(sortTypeData.conditionType)
            end)
        end
    end
end

function CoffeeTakeoutDialog:SetFilterType(conditionType)
    if conditionType == 9999 then
        ---全部区域
        self:FreshUI()
    else
        self:FreshUI(conditionType)
    end
    self:RefreshScrollView()
end

function CoffeeTakeoutDialog:OnGetItemByIndex(gridView, index, row, column)
    if index < 0 then
        return
    end
    local position = index + 1
    local cell = gridView:NewListViewItem(PrefabName)
    local id = self.orderIds[position]
    local data = self.data[tostring(id)]
    local cardNode = cell.transform:Find("OverseaManageTakeoutCardNode")
    ---@type TakeoutOrderCellNode
    local env = CfUtils.GetLuaScr(cardNode.gameObject, OrderCellNodePath)
    if env then
        env:SetTakOrderActionCallback(Bind(self, self.OnButtonAction))
        env:FreshUI(data)
    end
    return cell
end

---OnButtonAction
---@param data table @订单信息数据
---@param canOrder number @是否可下订单
function CoffeeTakeoutDialog:OnButtonAction(data, canOrder)
    print(table.dump(data, false, 3))
    local status = checkNumber(data.status)
    if status == Status.IDLE then
        ---是否可下订单, 记得中间的完成后返刷新当前页面的状态
        local isToMax = self:IsToMaxTime()
        if isToMax then
            GameUtils.Toast(localize("外卖配送次数已达每日上限"))
            return
        end

        if canOrder == 1 then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog, parameters = data }, {{id = Constants.UITypeIds.UIMaidCoffeeTakeoutDialog}})
        else
            ---跳转到料理制作
            local t = {}
            for _, v in pairs(data.cooks) do
                local goodsId = checkNumber(v.cookId)
                table.insert(t, { goodsId = goodsId, num = checkNumber(v.num) })
            end
            ---@type MaidCoffeeTakeOutOrderVo
            local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
            local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(data.orderId))
            CfUtils.StartCoroutineWithBlocker(function()
                coroutine.yield(UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, { type = MaidCoffeeConstants.CookingType.TakeOut,
                                                                                                                data = t,
                                                                                                                vo = takeOutOrderVo,
                                                                                                                dojo = data,
                                                                                                                cb = function()
                                                                                                                    if not isNull(self) and not isNull(self.controller) then
                                                                                                                        kTool.SetActive(self.controller.gameObject, true)
                                                                                                                        ---刷新下列表
                                                                                                                        self:RefreshScrollView()
                                                                                                                    end
                                                                                                                end })))
                kTool.SetActive(self.controller.gameObject, false)
            end)
        end
    elseif status == Status.FINISHED then
        ---领取的逻辑
        GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
            type = 1, orderId = data.id
        }, function(request, response)
            if checkNumber(response.errCode) == 0 then
                ---成功了
                local rdata = checkTable(response.data)
                local rewards = checkTable(rdata.rewards)
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local v = maidCoffeePlayerComponent:GetCardsByTeamId(data.teamId)
                for _, id in pairs(v) do
                    cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                end
                if #rewards > 0 then
                    GoodsUtils.DrawRewards(rewards)
                    ---关闭当前的页面
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = rdata.rewards,cb = function()
                                    local goodsId = string.split(self.controller.goodIds, ";")
                                    for i, v in pairs(rewards) do
                                        for i, goodsId in pairs(goodsId) do
                                            if checkNumber(v.goodsId) == checkNumber(goodsId) then
                                                GameUtils.StartFlyGoods(self.EffectStart.gameObject, checkNumber(v.goodsId))
                                            end
                                        end
                                    end
                                end }
                            }
                    )
                end
                Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = data, isNewOrder = 1 })
            end
        end)
    elseif status == Status.PROGRESSING then
        ---可快速完成的逻辑
        ---@type GoodsVo
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.CoffeeTakeoutTicket)
        print('---->>', table.dump(vo, false, 3))
        local ticket = 1
        local remainTime = checkNumber(data.remainTime)
        local fixTime = 0
        if vo.effectType == Constants.GoodsEffectType.EffectShortTime then
            ---缩短时间
            if remainTime > 0 then
                ticket = math.ceil(remainTime / checkNumber(vo.effectNum))
            end
            fixTime = checkNumber(vo.effectNum)
        end
        local havNo = GoodsUtils.GetThingNo(vo.id)
        local text = string.format_size_tag(string.format_color_tag(second_toHHMMSS(data.remainTime), '#d7184a'), 42)
        GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即完成订单', { _num_ = ticket, _name_ = vo.name }), function()
            if havNo < ticket then
                GameUtils.Toast(localize("_name_不足, 不能立即完成", { _name_ = vo.name }))
                return
            end
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
                type = 2, orderId = data.id
            }, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    ---成功了
                    local rdata = checkTable(response.data)
                    local rewards = checkTable(rdata.rewards)
                    GoodsUtils.DrawRewards({ { goodsId = vo.id, num = -ticket } })
                    ---@type CardComponent
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    local v = maidCoffeePlayerComponent:GetCardsByTeamId(data.teamId)
                    for _, id in pairs(v) do
                        cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                    end
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rdata.rewards)
                        ---关闭当前的页面
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = rdata.rewards }
                                }
                        )
                    end
                    ---重新请求一次，刷新定单
                    Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = data, isNewOrder = 1 })
                end
            end)
        end, function()

        end, localize('正在配送: _time_', { _time_ = text }), 4, { { goodsId = Constants.Currency.CoffeeTakeoutTicket, num = ticket } }, false, localize('每张外卖券可缩短_time_', { _time_ = CS.Engine.Tools.TimeUtils.HumanizeTimeString(fixTime) }), nil, checkNumber(data.id), UIModule.RootCanvas.transform)
    elseif status == Status.Cold then  ---冷确中

    end
end

function CoffeeTakeoutDialog:OnRejectAction()

end

function CoffeeTakeoutDialog:RefreshScrollView()
    if self.GridView.IsListViewInit then
        GameUtils.ReloadData(self.GridView, 0)
        GameUtils.ReloadData(self.GridView, table.count(self.orderIds))
    else
        self.GridView:InitGridView(table.count(self.orderIds), Bind(self, self.OnGetItemByIndex))
    end
end

function CoffeeTakeoutDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self.handler) then
            Events.RemoveListener(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED, self.handler)
        end
        self:RemoveListener()
        self.handler = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CoffeeTakeoutDialog